import React, { useState, useEffect } from 'react';
import { api } from '../services/api';
import StandardModal from './StandardModal';

function CategoryTable({ category, onBack, onEditCategory }) {
  const [tableData, setTableData] = useState(null);
  const [standards, setStandards] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [showStandardModal, setShowStandardModal] = useState(false);
  const [editingStandard, setEditingStandard] = useState(null);
  const [selectedArchiveStandardId, setSelectedArchiveStandardId] = useState(null);
  const [dateRange, setDateRange] = useState({
    startDate: new Date(new Date().getFullYear(), new Date().getMonth(), 1)
      .toISOString().split('T')[0],
    endDate: new Date().toISOString().split('T')[0]
  });

  useEffect(() => {
    loadTableData();
    loadStandards();
  }, [category, dateRange]);

  const loadTableData = async () => {
    setLoading(true);
    try {
      const data = await api.getCategoryTable(
        category.name,
        dateRange.startDate,
        dateRange.endDate
      );
      setTableData(data);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const loadStandards = async () => {
    try {
      const data = await api.getCategoryStandards(category.id);
      setStandards(data);
    } catch (err) {
      console.error('Error loading standards:', err);
    }
  };

  const handleDeleteStandard = async (standardId, standardName) => {
    if (!window.confirm(`Удалить стандарт "${standardName}"?`)) return;

    try {
      await api.deleteStandard(standardId);
      await loadStandards();
      if (selectedArchiveStandardId === standardId) {
        setSelectedArchiveStandardId(null);
      }
    } catch (err) {
      setError(err.message);
    }
  };

  const formatDate = (dateStr) => {
    if (!dateStr) return 'бессрочно';
    const d = new Date(dateStr);
    return d.toLocaleDateString('ru-RU');
  };

  const getStatusBadge = (standard) => {
    const today = new Date().toISOString().split('T')[0];
    const isActive = (!standard.endDate || standard.endDate >= today) && 
                     standard.startDate <= today;

    return isActive ? 
      <span className="status-badge active">Действующий</span> : 
      <span className="status-badge inactive">Недействующий</span>;
  };

  const handleDateChange = (e) => {
    setDateRange({
      ...dateRange,
      [e.target.name]: e.target.value
    });
  };

  // Разделяем стандарты на действующий и архивные
  const today = new Date().toISOString().split('T')[0];
  const activeStandard = standards.find(s => (!s.endDate || s.endDate >= today) && s.startDate <= today);
  const archiveStandards = standards.filter(s => (s.endDate && s.endDate < today) || s.startDate > today);

  if (loading) return <div className="loading">Загрузка данных...</div>;
  if (error) return <div className="error">Ошибка: {error}</div>;
  if (!tableData) return <div className="error">Нет данных</div>;

  return (
    <div className="category-table-container">
      {/* Верхняя панель с навигацией и заголовком */}
      <div className="category-header-panel">
        <button className="back-btn" onClick={onBack}>
          ← Назад
        </button>

        <h2 className="category-title">{category.name}</h2>

        <button 
          className="add-standard-btn"
          onClick={() => {
            setEditingStandard(null);
            setShowStandardModal(true);
          }}
        >
          + Добавить стандарт
        </button>
      </div>

      {/* Ряд со стандартами - действующий и архив */}
      {standards.length > 0 && (
        <div className="standards-row">
          {/* Действующий стандарт */}
          {activeStandard && (
            <div className="active-standard-wrapper">
              <div className="standard-card active">
                <div className="standard-card-header">
                  <h4>{activeStandard.name}</h4>
                  <div className="standard-actions">
                    <button 
                      className="edit-btn small"
                      onClick={() => {
                        setEditingStandard(activeStandard);
                        setShowStandardModal(true);
                      }}
                      title="Редактировать стандарт"
                    >
                      ✏️
                    </button>
                    <button 
                      className="delete-btn small"
                      onClick={() => handleDeleteStandard(activeStandard.id, activeStandard.name)}
                      title="Удалить стандарт"
                    >
                      🗑️
                    </button>
                  </div>
                </div>

                {getStatusBadge(activeStandard)}

                {activeStandard.description && (
                  <p className="standard-description">{activeStandard.description}</p>
                )}

                <div className="standard-dates">
                  <div className="date-item">
                    <span className="date-label">Ввод:</span>
                    <span className="date-value">{formatDate(activeStandard.startDate)}</span>
                  </div>
                  <div className="date-item">
                    <span className="date-label">Вывод:</span>
                    <span className="date-value">{formatDate(activeStandard.endDate)}</span>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* Архив стандартов - стопка */}
          {archiveStandards.length > 0 && (
            <div className="archive-standards-wrapper">
              <div className="standards-stack">
                {archiveStandards.map((standard, index) => (
                  <div key={standard.id} className="stack-item-container">
                    <div 
                      className={`stack-item ${selectedArchiveStandardId === standard.id ? 'expanded' : ''}`}
                      style={{ 
                        zIndex: archiveStandards.length - index,
                        marginTop: index > 0 ? '-45px' : '0',
                        marginLeft: index > 0 ? `${index * 5}px` : '0'
                      }}
                      onClick={() => setSelectedArchiveStandardId(
                        selectedArchiveStandardId === standard.id ? null : standard.id
                      )}
                    >
                      {selectedArchiveStandardId === standard.id ? (
                        // Развернутая карточка архива
                        <div className="standard-card expanded-archive">
                          <div className="standard-card-header">
                            <h4>{standard.name}</h4>
                            <div className="standard-actions">
                              <button 
                                className="edit-btn small"
                                onClick={(e) => {
                                  e.stopPropagation();
                                  setEditingStandard(standard);
                                  setShowStandardModal(true);
                                }}
                                title="Редактировать стандарт"
                              >
                                ✏️
                              </button>
                              <button 
                                className="delete-btn small"
                                onClick={(e) => {
                                  e.stopPropagation();
                                  handleDeleteStandard(standard.id, standard.name);
                                }}
                                title="Удалить стандарт"
                              >
                                🗑️
                              </button>
                            </div>
                          </div>

                          {getStatusBadge(standard)}

                          {standard.description && (
                            <p className="standard-description">{standard.description}</p>
                          )}

                          <div className="standard-dates">
                            <div className="date-item">
                              <span className="date-label">Ввод:</span>
                              <span className="date-value">{formatDate(standard.startDate)}</span>
                            </div>
                            <div className="date-item">
                              <span className="date-label">Вывод:</span>
                              <span className="date-value">{formatDate(standard.endDate)}</span>
                            </div>
                          </div>
                        </div>
                      ) : (
                        // Свернутая карточка архива (превью)
                        <div className="stack-item-preview">
                          <span className="stack-item-name">{standard.name}</span>
                          <span className="stack-item-date">
                            {formatDate(standard.startDate)} - {formatDate(standard.endDate)}
                          </span>
                        </div>
                      )}
                    </div>
                  </div>
                ))}
              </div>
              {archiveStandards.length > 0 && (
                <div className="archive-label">
                  Архив ({archiveStandards.length})
                </div>
              )}
            </div>
          )}
        </div>
      )}

      {/* Панель с диапазоном дат и кнопкой редактирования */}
      <div className="date-controls-panel">
        <div className="date-range-controls">
          <label>
            С:
            <input
              type="date"
              name="startDate"
              value={dateRange.startDate}
              onChange={handleDateChange}
            />
          </label>
          <label>
            По:
            <input
              type="date"
              name="endDate"
              value={dateRange.endDate}
              onChange={handleDateChange}
            />
          </label>
        </div>

        <button 
          className="edit-category-btn"
          onClick={() => onEditCategory(category)}
        >
          Редактировать
        </button>
      </div>

      {/* Таблица с данными */}
      <div className="table-wrapper">
        <table className="category-table">
          <thead>
            <tr>
              <th>Дата</th>
              {tableData.practices.map(practice => (
                <th key={practice}>{practice}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {tableData.rows.map(row => {
              const formattedDate = new Date(row.date).toLocaleDateString('ru-RU');
              return (
                <tr key={row.date}>
                  <td>{formattedDate}</td>
                  {tableData.practices.map(practice => (
                    <td key={practice} className="practice-value">
                      {row.values[practice] || '-'}
                    </td>
                  ))}
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {showStandardModal && (
        <StandardModal
          category={category}
          standard={editingStandard}
          onClose={() => {
            setShowStandardModal(false);
            setEditingStandard(null);
          }}
          onUpdate={() => {
            loadStandards();
          }}
        />
      )}
    </div>
  );
}

export default CategoryTable;
